{
  "aktywnosci": [
    {
      "tytul": "Słuchamy ciszy – zabawa z dźwiękiem i bezruchem",
      "opis": "Przygotuj cichy kącik z poduszkami i lekkimi kocykami. Dzieci siadają w kole, nauczyciel mówi: 'Zamknij oczy i posłuchaj, co słychać w ciszy'. Przez 1–2 minuty wszyscy milczą, potem dzieci opowiadają, co usłyszały (np. tykanie zegara, oddech, szum za oknem). Następnie nauczyciel gra na delikatnym instrumencie (np. dzwoneczki, trójkąt) coraz ciszej – dzieci reagują, robiąc się nieruchome jak posągi. Ćwiczy to uwagę i wyciszenie."
    },
    {
      "tytul": "Wdech – wydech: balonik relaksu",
      "opis": "Każde dziecko dostaje mały balonik (bez sznurka). Nauczyciel pokazuje, jak nadmuchać balon powoli, głęboko oddychając – dzieci naśladują, ale tylko do połowy (bez wiązania). Potem wypuszczają powietrze z balonu, słuchając, jak ucieka. Zabawa powtarza się 3–4 razy. Jeśli baloniki są zbyt trudne dla młodszych, można dmuchać na waciki na stoliku – kto dmuchnie najdelikatniej, nie zrzucając wacika. Ćwiczy to kontrolę oddechu i wycisza przed odpoczynkiem."
    },
    {
      "tytul": "Kolorowanka antystresowa – mandala z darów natury",
      "opis": "Nauczyciel przygotowuje duże, proste kontury mandali (np. koło z podziałem na 4–6 pól) na kartkach A4. Dzieci otrzymują pastele olejne lub grube kredki w stonowanych kolorach (błękit, zieleń, fiolet, beż). W ciszy (może grać cicha muzyka relaksacyjna) dzieci wypełniają pola kolorami – mogą też naklejać na kontur małe listki, płatki kwiatów lub kawałki sznurka. Nauczyciel przechadza się i chwali starania. Po skończeniu mandale można powiesić na gazetce jako 'kącik spokoju'."
    }
  ]
}
